-- =============================================================
-- Ethiopia Scout Association — General Assembly Voting System
-- Applied automatically at every server start-up (src/db.ts ensureSchema) and
-- by `npm run db:migrate`. Every statement is idempotent, so it is safe to
-- re-run on an existing database (plain PostgreSQL 14+; nothing here is
-- Supabase-specific).
-- =============================================================

-- Voting members. Credentials (token + password) are generated by the
-- National Office with scripts/generate-credentials.ts and distributed
-- out-of-band. A member binds their Telegram account on first login.
create table if not exists members (
  id               uuid primary key default gen_random_uuid(),
  token_id         text unique not null,          -- e.g. ESA-2026-K7M2P
  password_hash    text not null,                 -- bcrypt
  full_name        text,
  region           text,
  telegram_user_id bigint unique,                 -- bound on first successful login
  registered_at    timestamptz,
  failed_attempts  int not null default 0,
  locked_until     timestamptz,
  is_active        boolean not null default true,
  created_at       timestamptz not null default now()
);
-- Votes per ballot (council vote weight; 1 = one delegate, one vote).
alter table members add column if not exists vote_weight int not null default 1;

-- Resolutions to be voted on during the assembly.
create table if not exists resolutions (
  id                  uuid primary key default gen_random_uuid(),
  code                text unique not null,        -- short handle: R1, R2, ...
  title               text not null,
  description         text,
  options             jsonb not null,              -- array of option labels
  anonymous           boolean not null default true, -- secret ballot?
  quorum              int,                         -- % of eligible (active) members who must cast a ballot (null = none)
  threshold           text not null default 'simple'
                      check (threshold in ('simple', 'two_thirds')),
  status              text not null default 'draft'
                      check (status in ('draft', 'open', 'closed')),
  announce_chat_id    bigint,                      -- where /announce was posted
  announce_thread_id  bigint,                      -- forum topic id, if any
  closes_at           timestamptz,                 -- optional auto-close deadline
  opened_at           timestamptz,
  closed_at           timestamptz,
  created_at          timestamptz not null default now()
);

-- Who has cast a ballot (double-vote guard). Never exposes the choice.
create table if not exists ballots (
  resolution_id uuid not null references resolutions(id) on delete cascade,
  member_id     uuid not null references members(id) on delete cascade,
  created_at    timestamptz not null default now(),
  primary key (resolution_id, member_id)
);

-- The actual choices. For secret ballots member_id is NULL, so the choice
-- can never be linked back to a person; for open ballots it is kept so the
-- member may change their vote until the resolution closes.
create table if not exists votes (
  id            uuid primary key default gen_random_uuid(),
  resolution_id uuid not null references resolutions(id) on delete cascade,
  member_id     uuid references members(id) on delete cascade,
  choice_index  int not null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create unique index if not exists votes_one_per_member
  on votes (resolution_id, member_id) where member_id is not null;
create index if not exists votes_by_resolution on votes (resolution_id);
-- Weight stamped on the vote when it is cast (secret ballots keep no member id).
alter table votes add column if not exists weight int not null default 1;

-- Minimal audit trail of sensitive actions.
create table if not exists audit_log (
  id         bigint generated always as identity primary key,
  actor      text not null,           -- telegram id or 'system'
  action     text not null,
  details    jsonb,
  created_at timestamptz not null default now()
);

-- Mini App support: key/value settings, known assembly group topics,
-- and admins managed from the app (in addition to ADMIN_TELEGRAM_IDS).
create table if not exists app_settings (
  key        text primary key,
  value      jsonb not null,
  updated_at timestamptz not null default now()
);

-- Forum topics the bot has seen in the assembly group. thread_id 0 = General.
create table if not exists chat_topics (
  chat_id    bigint not null,
  thread_id  bigint not null default 0,
  name       text,
  chat_title text,
  updated_at timestamptz not null default now(),
  primary key (chat_id, thread_id)
);

-- Additional admins added from the Mini App (env ADMIN_TELEGRAM_IDS still apply).
create table if not exists admins (
  telegram_user_id bigint primary key,
  name             text,
  added_by         text,
  created_at       timestamptz not null default now()
);

-- Atomically record a ballot + vote. Returns:
--   'ok'            first vote recorded
--   'changed'       open-ballot vote updated
--   'already_voted' secret ballot, vote cannot be changed
--   'not_open'      resolution is not accepting votes
--   'not_found'     unknown resolution
create or replace function cast_vote(
  p_resolution_id uuid,
  p_member_id     uuid,
  p_choice        int
) returns text
language plpgsql
security definer
as $$
declare
  v_res resolutions%rowtype;
  v_weight int;
begin
  select * into v_res from resolutions where id = p_resolution_id for update;
  select coalesce(vote_weight, 1) into v_weight from members where id = p_member_id;
  if v_weight is null then
    v_weight := 1;
  end if;
  if not found then
    return 'not_found';
  end if;
  if v_res.status <> 'open' then
    return 'not_open';
  end if;
  if p_choice < 0 or p_choice >= jsonb_array_length(v_res.options) then
    return 'bad_choice';
  end if;

  if exists (select 1 from ballots
             where resolution_id = p_resolution_id and member_id = p_member_id) then
    if v_res.anonymous then
      return 'already_voted';
    end if;
    update votes
       set choice_index = p_choice, weight = v_weight, updated_at = now()
     where resolution_id = p_resolution_id and member_id = p_member_id;
    return 'changed';
  end if;

  insert into ballots (resolution_id, member_id)
  values (p_resolution_id, p_member_id);

  insert into votes (resolution_id, member_id, choice_index, weight)
  values (p_resolution_id,
          case when v_res.anonymous then null else p_member_id end,
          p_choice,
          v_weight);
  return 'ok';
end;
$$;

-- Tally used for results: sums the vote weights (1 per vote unless the
-- member's council gives each delegate several votes).
create or replace function tally_votes(p_resolution_id uuid)
returns table (choice_index int, votes bigint)
language sql
security definer
as $$
  select v.choice_index, coalesce(sum(v.weight), 0)::bigint
    from votes v
   where v.resolution_id = p_resolution_id
   group by v.choice_index
   order by v.choice_index;
$$;

-- Row-level security with no policies: the bot connects as the table owner
-- (which bypasses RLS); any other database role can read nothing.
alter table members     enable row level security;
alter table resolutions enable row level security;
alter table ballots     enable row level security;
alter table votes       enable row level security;
alter table audit_log   enable row level security;
alter table app_settings enable row level security;
alter table chat_topics  enable row level security;
alter table admins       enable row level security;

-- Councils (regional / sectional bodies) that receive voting invitations.
-- Each invitation is a members row linked to its council with a seat number;
-- the token prefix is the council code (e.g. ADD-K7M2P).
create table if not exists councils (
  id         uuid primary key default gen_random_uuid(),
  name       text unique not null,
  code       text unique not null,          -- short token prefix, e.g. ADD
  seats      int not null default 1,        -- number of voting delegates
  vote_weight int not null default 1,       -- votes carried by each delegate
  created_at timestamptz not null default now()
);
alter table councils add column if not exists vote_weight int not null default 1;
alter table members add column if not exists council_id uuid references councils(id) on delete set null;
alter table members add column if not exists seat_no int;
-- Delegate's phone number (international form, e.g. +251911234567), when given instead of / besides a name.
alter table members add column if not exists phone text;
-- Active members at the moment voting closed: the base the quorum percentage is measured against.
alter table resolutions add column if not exists eligible_count int;

-- Activation code: voters must enter a 4-digit code shown in the meeting
-- (screen or video-call chat) before they can vote on a resolution, proving
-- they are present. Generated when voting opens; who entered it is recorded.
alter table resolutions add column if not exists activation_required boolean not null default true;
alter table resolutions add column if not exists activation_code text;
-- Set when the deadline passed without quorum: the vote stays open, the admins
-- decide (extend / close as not valid / close and redo), and it closes on its
-- own as soon as quorum is reached.
alter table resolutions add column if not exists awaiting_quorum_since timestamptz;
create table if not exists vote_activations (
  resolution_id uuid not null references resolutions(id) on delete cascade,
  member_id     uuid not null references members(id) on delete cascade,
  activated_at  timestamptz not null default now(),
  primary key (resolution_id, member_id)
);
alter table vote_activations enable row level security;

-- People the bot has seen in the assembly group (Telegram does not let a bot
-- list members, so they are learned from joins, join requests and messages).
-- Setup shows the ones who are not registered members so an admin can
-- register them or remove them from the group.
create table if not exists group_people (
  chat_id       bigint not null,
  user_id       bigint not null,
  first_name    text,
  last_name     text,
  username      text,
  status        text not null default 'member'
                check (status in ('member', 'left', 'kicked', 'pending')),
  source        text,            -- joined | added | join_request | posted
  added_by      bigint,          -- who added them, when known
  first_seen_at timestamptz not null default now(),
  last_seen_at  timestamptz not null default now(),
  primary key (chat_id, user_id)
);
alter table group_people enable row level security;
create index if not exists members_by_council on members (council_id);
alter table councils enable row level security;

-- =============================================================
-- Organisations. Kene Voting System serves several assemblies (Ethiopia Scout
-- Association, Association of Ethiopian Architects, ...) from one bot and one
-- database; every assembly row below belongs to one organisation, and the
-- application scopes every query to the organisation of the request.
-- =============================================================
create table if not exists organizations (
  id            uuid primary key default gen_random_uuid(),
  name_en       text not null,                    -- "Association of Ethiopian Architects"
  name_am       text,                             -- Amharic name, optional
  short_code    text not null,                    -- invitation-code prefix, e.g. AEA
  assembly_en   text,                             -- "General Assembly 2026"
  assembly_am   text,
  office_en     text,                             -- who issues invitations: "National Office", "Secretariat"
  office_am     text,
  voter_term    text not null default 'delegate', -- preset key (src/services/orgs.ts)
  group_term    text not null default 'council',  -- preset key
  group_chat_id bigint unique,                    -- the linked Telegram group
  group_title   text,
  created_at    timestamptz not null default now()
);
alter table organizations enable row level security;

alter table members      add column if not exists org_id uuid references organizations(id) on delete cascade;
alter table councils     add column if not exists org_id uuid references organizations(id) on delete cascade;
alter table resolutions  add column if not exists org_id uuid references organizations(id) on delete cascade;
alter table chat_topics  add column if not exists org_id uuid references organizations(id) on delete cascade;
alter table group_people add column if not exists org_id uuid references organizations(id) on delete cascade;
alter table admins       add column if not exists org_id uuid references organizations(id) on delete cascade;
alter table app_settings add column if not exists org_id uuid references organizations(id) on delete cascade;
alter table audit_log    add column if not exists org_id uuid references organizations(id) on delete set null;

-- Data created before organisations existed belongs to the Ethiopia Scout Association.
insert into organizations (id, name_en, name_am, short_code, assembly_en, assembly_am, office_en, office_am)
select '00000000-0000-4000-8000-00000000e5a0', 'Ethiopia Scout Association', 'የኢትዮጵያ ስካውት ማኅበር', 'ESA',
       'General Assembly 2026', 'ጠቅላላ ጉባኤ 2026', 'National Office', 'ብሔራዊ ጽሕፈት ቤት'
 where not exists (select 1 from organizations)
   and (exists (select 1 from members) or exists (select 1 from resolutions) or exists (select 1 from councils)
        or exists (select 1 from app_settings) or exists (select 1 from admins) or exists (select 1 from chat_topics));
update members      set org_id = '00000000-0000-4000-8000-00000000e5a0' where org_id is null and exists (select 1 from organizations where id = '00000000-0000-4000-8000-00000000e5a0');
update councils     set org_id = '00000000-0000-4000-8000-00000000e5a0' where org_id is null and exists (select 1 from organizations where id = '00000000-0000-4000-8000-00000000e5a0');
update resolutions  set org_id = '00000000-0000-4000-8000-00000000e5a0' where org_id is null and exists (select 1 from organizations where id = '00000000-0000-4000-8000-00000000e5a0');
update chat_topics  set org_id = '00000000-0000-4000-8000-00000000e5a0' where org_id is null and exists (select 1 from organizations where id = '00000000-0000-4000-8000-00000000e5a0');
update group_people set org_id = '00000000-0000-4000-8000-00000000e5a0' where org_id is null and exists (select 1 from organizations where id = '00000000-0000-4000-8000-00000000e5a0');
update admins       set org_id = '00000000-0000-4000-8000-00000000e5a0' where org_id is null and exists (select 1 from organizations where id = '00000000-0000-4000-8000-00000000e5a0');
update app_settings set org_id = '00000000-0000-4000-8000-00000000e5a0' where org_id is null and exists (select 1 from organizations where id = '00000000-0000-4000-8000-00000000e5a0');
update audit_log    set org_id = '00000000-0000-4000-8000-00000000e5a0'
 where org_id is null and exists (select 1 from organizations where id = '00000000-0000-4000-8000-00000000e5a0');
-- The linked group moved from the 'group' setting to the organisation row.
update organizations o
   set group_chat_id = (s.value->>'chat_id')::bigint, group_title = s.value->>'title'
  from app_settings s
 where s.org_id = o.id and s.key = 'group' and o.group_chat_id is null
   and not exists (select 1 from organizations x where x.group_chat_id = (s.value->>'chat_id')::bigint);
delete from app_settings where key = 'group';

alter table members      alter column org_id set not null;
alter table councils     alter column org_id set not null;
alter table resolutions  alter column org_id set not null;
alter table chat_topics  alter column org_id set not null;
alter table group_people alter column org_id set not null;
alter table admins       alter column org_id set not null;
alter table app_settings alter column org_id set not null;

-- Uniqueness is now per organisation: R1 exists in every assembly, a council
-- name may repeat across organisations, and one Telegram account can be a
-- member (or admin) of several organisations. Invitation codes stay unique
-- everywhere, so a code alone tells which organisation it belongs to.
do $$
begin
  if exists (select 1 from pg_constraint where conname = 'members_telegram_user_id_key') then
    alter table members drop constraint members_telegram_user_id_key;
  end if;
  if exists (select 1 from pg_constraint where conname = 'resolutions_code_key') then
    alter table resolutions drop constraint resolutions_code_key;
  end if;
  if exists (select 1 from pg_constraint where conname = 'councils_name_key') then
    alter table councils drop constraint councils_name_key;
  end if;
  if exists (select 1 from pg_constraint where conname = 'councils_code_key') then
    alter table councils drop constraint councils_code_key;
  end if;
  if exists (select 1 from pg_constraint c join pg_class t on t.oid = c.conrelid
              where t.relname = 'app_settings' and c.contype = 'p' and array_length(c.conkey, 1) = 1) then
    alter table app_settings drop constraint app_settings_pkey;
    alter table app_settings add primary key (org_id, key);
  end if;
  if exists (select 1 from pg_constraint c join pg_class t on t.oid = c.conrelid
              where t.relname = 'admins' and c.contype = 'p' and array_length(c.conkey, 1) = 1) then
    alter table admins drop constraint admins_pkey;
    alter table admins add primary key (org_id, telegram_user_id);
  end if;
end $$;
create unique index if not exists members_org_telegram on members (org_id, telegram_user_id);
create unique index if not exists resolutions_org_code on resolutions (org_id, code);
create unique index if not exists councils_org_name on councils (org_id, name);
create unique index if not exists councils_org_code on councils (org_id, code);
create index if not exists members_by_org on members (org_id);
create index if not exists resolutions_by_org on resolutions (org_id);
create index if not exists audit_by_org on audit_log (org_id, created_at);

-- How members take part: 'councils' (bodies send representative delegates, as
-- in scouting) or 'direct' (every member votes for themselves, as in a share
-- company or a professional association — no councils, votes per member).
alter table organizations add column if not exists structure text not null default 'councils';

-- Invitation recognised in the bot chat (QR scanned) but not completed yet.
-- Kept outside any organisation: the code itself says which one it is.
create table if not exists pending_invitations (
  telegram_user_id bigint primary key,
  token_id         text not null,
  created_at       timestamptz not null default now()
);
alter table pending_invitations enable row level security;

-- Which organisation a person's private chat with the bot is about, when they
-- belong to several (chosen with /org).
create table if not exists user_active_org (
  telegram_user_id bigint primary key,
  org_id           uuid not null references organizations(id) on delete cascade,
  updated_at       timestamptz not null default now()
);
alter table user_active_org enable row level security;

-- =============================================================
-- The group screen: sign in / out, language, read-only topics, live board.
-- =============================================================
-- Presence in the session: 'available' or 'away' (signed in), 'out' (signed
-- out with Logout — counts as absent and cannot vote until they sign in again).
alter table members add column if not exists presence text not null default 'available';
alter table members add column if not exists presence_at timestamptz;
-- Profile photo chosen in the Mini App (a small data: URL); null = the Telegram photo.
alter table members add column if not exists avatar text;
-- Language a person chose for the bot and the Mini App ('en' | 'am'; null = both).
-- Per person, across organisations.
create table if not exists user_prefs (
  telegram_user_id bigint primary key,
  lang             text,
  updated_at       timestamptz not null default now()
);
alter table user_prefs enable row level security;
-- Topics where only admins post (closed in Telegram); members get a pinned
-- button panel there instead of the buttons under the message box.
alter table chat_topics add column if not exists read_only boolean not null default false;
alter table chat_topics add column if not exists keyboard_message_id bigint; -- the "⌨️" message carrying the buttons
alter table chat_topics add column if not exists panel_message_id bigint;    -- the pinned button panel (read-only topics)

-- =============================================================
-- Motions: what a member proposes before it becomes a resolution.
-- Moved (in a topic, from the app) → seconded by another member → the chair
-- (an admin) states it, rules it out of order, or merges it → debate, with
-- amendments (motions of kind 'amendment' on it) → put to the vote as a
-- resolution → adopted or lost. Withdrawn by the mover until it is stated;
-- lapsed when nobody seconds it.
-- =============================================================
create table if not exists motions (
  id                 uuid primary key default gen_random_uuid(),
  org_id             uuid not null references organizations(id) on delete cascade,
  code               text not null,                  -- M1, M2, ... (amendments: M3-A1)
  kind               text not null default 'main'
                     check (kind in ('main', 'constitutional', 'amendment')),
  parent_id          uuid references motions(id) on delete cascade, -- the motion an amendment changes
  title              text not null,
  body               text not null,                  -- the wording ("That the assembly ...")
  original_body      text,                           -- the wording as moved, once amendments changed it
  replaced_body      text,                           -- (adopted amendment) the motion's wording it replaced
  status             text not null default 'proposed'
                     check (status in ('proposed', 'seconded', 'stated', 'voting', 'adopted', 'lost',
                                       'withdrawn', 'out_of_order', 'merged', 'lapsed')),
  mover_member_id    uuid references members(id) on delete set null,
  mover_name         text,
  seconder_member_id uuid references members(id) on delete set null,
  seconder_name      text,
  from_floor         boolean not null default false, -- entered by the chair for a motion made aloud
  late_notice        boolean not null default false, -- constitutional motion moved after the notice deadline
  chat_id            bigint,                         -- the topic it was moved in, and its card there
  thread_id          bigint,
  message_id         bigint,
  resolution_id      uuid references resolutions(id) on delete set null,
  merged_into        uuid references motions(id) on delete set null,
  reason             text,                           -- why it was ruled out of order / withdrawn / merged
  seconded_at        timestamptz,
  stated_at          timestamptz,
  decided_at         timestamptz,
  created_at         timestamptz not null default now()
);
alter table motions enable row level security;
create unique index if not exists motions_org_code on motions (org_id, code);
create index if not exists motions_by_org on motions (org_id, created_at);
-- The motion a resolution puts to the vote.
alter table resolutions add column if not exists motion_id uuid references motions(id) on delete set null;

-- =============================================================
-- Kene Voting as a business: anyone signs in with Telegram, creates an
-- organisation (its creator is its first administrator) and buys a plan by
-- bank / mobile-money transfer with a receipt the platform administrators
-- approve. Organisations created by the platform administrators are exempt.
-- Without an active plan an organisation works with a small number of
-- members (the trial cap), enough to set up and rehearse.
-- =============================================================
-- Existing organisations (created before self-service) stay exempt: the default is true,
-- self-service creation inserts false.
alter table organizations add column if not exists billing_exempt boolean not null default true;
alter table organizations add column if not exists created_by     bigint;      -- Telegram ID of the creator
alter table organizations add column if not exists paid_until     timestamptz; -- end of the paid period
alter table organizations add column if not exists member_cap     integer;     -- members the paid plan allows (null = no limit)
alter table organizations add column if not exists plan_id        uuid;

-- Someone who signed in on the business pages (creators of organisations).
create table if not exists biz_accounts (
  telegram_user_id bigint primary key,
  first_name       text,
  last_name        text,
  username         text,
  ref_code         text not null unique,   -- their share link: /business/?ref=<code>
  referred_by      bigint,                 -- the account whose link brought them (link only, no reward)
  created_at       timestamptz not null default now(),
  last_login_at    timestamptz not null default now()
);
alter table biz_accounts enable row level security;

create table if not exists biz_plans (
  id            uuid primary key default gen_random_uuid(),
  name_en       text not null,
  name_am       text,
  description   text,
  duration_days integer not null check (duration_days > 0),
  member_cap    integer check (member_cap is null or member_cap > 0), -- null = no limit
  active        boolean not null default true,
  sort          integer not null default 0,
  created_at    timestamptz not null default now()
);
alter table biz_plans enable row level security;

-- A plan's price in each country (ISO-2) where it is sold.
create table if not exists biz_plan_prices (
  plan_id  uuid not null references biz_plans(id) on delete cascade,
  country  text not null,
  price    numeric(12, 2) not null check (price >= 0),
  currency text not null,
  primary key (plan_id, country)
);
alter table biz_plan_prices enable row level security;

-- Where creators send the money, per country.
create table if not exists biz_pay_methods (
  id             uuid primary key default gen_random_uuid(),
  country        text not null,
  provider       text not null,           -- "Commercial Bank of Ethiopia", "telebirr"
  account_name   text not null,
  account_number text not null,
  note           text,
  active         boolean not null default true,
  sort           integer not null default 0,
  created_at     timestamptz not null default now()
);
alter table biz_pay_methods enable row level security;

create table if not exists biz_payments (
  id               uuid primary key default gen_random_uuid(),
  org_id           uuid not null references organizations(id) on delete cascade,
  telegram_user_id bigint not null,       -- who paid
  plan_id          uuid references biz_plans(id) on delete set null,
  plan_name        text not null,         -- as bought
  duration_days    integer not null,
  member_cap       integer,
  country          text not null,
  amount           numeric(12, 2) not null,
  currency         text not null,
  method_id        uuid references biz_pay_methods(id) on delete set null,
  method_label     text,                  -- as shown when paying
  reference        text not null,         -- transaction reference on the receipt
  receipt          text,                  -- the receipt image (small data: URL)
  status           text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),
  review_note      text,
  reviewed_by      bigint,
  reviewed_at      timestamptz,
  period_start     timestamptz,           -- set on approval
  period_end       timestamptz,
  created_at       timestamptz not null default now()
);
alter table biz_payments enable row level security;
create index if not exists biz_payments_by_status on biz_payments (status, created_at);
create index if not exists biz_payments_by_org on biz_payments (org_id, created_at);

-- Signing in on the business pages through the bot: the page shows a link
-- t.me/<bot>?start=weblogin_<nonce>; the bot marks the nonce with the account
-- that tapped Start; the page then collects its session.
create table if not exists biz_logins (
  nonce            text primary key,
  telegram_user_id bigint,
  first_name       text,
  last_name        text,
  username         text,
  ref_code         text,
  created_at       timestamptz not null default now(),
  claimed_at       timestamptz
);
alter table biz_logins enable row level security;

-- Platform-wide business settings (trial member cap, ...).
create table if not exists biz_settings (
  key        text primary key,
  value      jsonb not null,
  updated_at timestamptz not null default now()
);
alter table biz_settings enable row level security;
